# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SELAMLAŞMA, TANIŞMA VE VEDALAŞMA DİYALOGLARI</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Selamlaşma Kalıpları</text>\n  <text x="125" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">اَلسَّلَامُ عَلَيْكُمْ ⇄ وَعَلَيْكُمُ السَّلَامُ</text>\n  <text x="125" y="115" text-anchor="middle" font-size="11" fill="#334155">Selamün aleyküm ⇄ Aleyküm selam</text>\n  <text x="125" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">صَبَاحُ الْخَيْرِ ⇄ صَبَاحُ النُّورِ</text>\n  <text x="125" y="160" text-anchor="middle" font-size="11" fill="#334155">Hayırlı sabahlar (Günaydın)</text>\n  <text x="125" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">مَسَاءُ الْخَيْرِ ⇄ مَسَاءُ النُّورِ</text>\n  <text x="125" y="206" text-anchor="middle" font-size="11" fill="#334155">Hayırlı akşamlar (İyi akşamlar)</text>\n  <text x="125" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">أَهْلًا وَسَهْلًا ⇄ أَهْلًا بِكَ / بِكِ</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tanışma ve Hal Hatır</text>\n  <text x="350" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">مَا اسْمُكَ؟ / مَا اسْمُكِ؟</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#334155">Adın ne? (Eril: -ke / Dişil: -ki)</text>\n  <text x="350" y="136" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">اِسْمِي أَحْمَدُ / اِسْمِي زَيْنَبُ</text>\n  <text x="350" y="162" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">كَيْفَ حَالُكَ؟ / كَيْفَ حَالُكِ؟</text>\n  <text x="350" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">بِخَيْرٍ، وَالْحَمْدُ لِلَّهِ</text>\n  <text x="350" y="206" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">تَشَرَّفْتُ ⇄ فُرْصَةٌ سَعِيدَةٌ</text>\n  <text x="350" y="226" text-anchor="middle" font-size="11" fill="#334155">Memnun oldum ⇄ Güzel bir fırsat</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Vedalaşma ve Nezaket</text>\n  <text x="575" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">إِلَى اللِّقَاءِ (Görüşmek üzere)</text>\n  <text x="575" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">مَعَ السَّلَامَةِ (Güle güle)</text>\n  <text x="575" y="149" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">فِي أَمَانِ اللهِ (Allah\'a emanet ol)</text>\n  <text x="575" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">شُكْرًا (Teşekkürler) ⇄ عَفْوًا (Rica ederim)</text>\n  <text x="575" y="208" text-anchor="middle" font-size="12" font-weight="bold" fill="#713f12">مِنْ فَضْلِكَ / مِنْ فَضْلِكِ</text>\n  <text x="575" y="226" text-anchor="middle" font-size="11" fill="#334155">Lütfen (Erkek / Kız muhatap)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HARFLERİN HAREKELERLE OKUNUŞU VE KELİME BİRLEŞTİRME</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Üç Temel Hareke (Ses İşaretleri)</text>\n  <text x="180" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">• Fetha (Üstün): بَ (Be) - قَ (Ka)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11" fill="#475569">Harfin üzerine yazılır; ince harfleri e, kalınları a okutur.</text>\n  <text x="180" y="152" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">• Kesra (Esre): بِ (Bi) - قِ (Kı)</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11" fill="#475569">Harfin altına yazılır; ince harfleri i, kalınları ı okutur.</text>\n  <text x="180" y="202" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">• Damme (Ötre): بُ (Bü) - قُ (Ku)</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" fill="#475569">Harfin üzerine vav benzeri konur; ü veya u sesi verir.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Harf Birleştirme ve Ayrık Harfler</text>\n  <text x="520" y="100" text-anchor="middle" font-size="13" font-weight="bold" fill="#9f1239">كَ + تَ + بَ = كَتَبَ (Ketebe)</text>\n  <text x="520" y="126" text-anchor="middle" font-size="13" font-weight="bold" fill="#9f1239">قَ + لَ + مٌ = قَلَمٌ (Kalemün)</text>\n  <text x="520" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#881337">Sonraki Harfle Birleşmeyen 6 Harf:</text>\n  <text x="520" y="182" text-anchor="middle" font-size="16" font-weight="bold" fill="#e11d48">ا - د - ذ - ر - ز - و</text>\n  <text x="520" y="205" text-anchor="middle" font-size="11" fill="#475569">Elif, Dal, Zel, Ra, Ze ve Vav harfleri</text>\n  <text x="520" y="223" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Örnek: دَ + رَ + سَ = دَرَسَ (Derese)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SORU-CEVAP KALIPLARI VE SINIF İÇİ YÖNERGELER</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Kimlik ve Doğrulama Soruları</text>\n  <text x="182" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">هَلْ أَنْتَ طَالِبٌ؟ (Sen erkek öğrenci misin?)</text>\n  <text x="182" y="124" text-anchor="middle" font-size="12" fill="#0f172a">نَعَمْ، أَنَا طَالِبٌ. (Evet, ben öğrenciyim.)</text>\n  <text x="182" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">هَلْ أَنْتِ مُعَلِّمَةٌ؟ (Sen kadın öğretmen misin?)</text>\n  <text x="182" y="178" text-anchor="middle" font-size="12" fill="#0f172a">لَا، أَنَا طَالِبَةٌ. (Hayır, ben kız öğrenciyim.)</text>\n  <text x="182" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#0891b2">«اَلسَّلَامُ قَبْلَ الْكَلَامِ» (Selam kelamdan öncedir.)</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Eril ve Dişil Sınıf Yönergeleri</text>\n  <text x="517" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">قُمْ (Kalk - Eril)  |  قُومِي (Kalk - Dişil)</text>\n  <text x="517" y="134" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">اِجْلِسْ (Otur - Eril)  |  اِجْلِسِي (Otur - Dişil)</text>\n  <text x="517" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">اِقْرَأْ (Oku - Eril)  |  اِقْرَئِي (Oku - Dişil)</text>\n  <text x="517" y="194" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">اُكْتُبْ (Yaz - Eril)  |  اُكْتُبِي (Yaz - Dişil)</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" fill="#92400e">Hitap ünlemi: يَا أَحْمَدُ (Ey Ahmet!) / يَا زَيْنَبُ (Ey Zeynep!)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
